"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4109],{22305:e=>{e.exports=JSON.parse('{"functions":[{"name":"Start","desc":"Starts moving, turning or sizing the selection.","params":[{"name":"ctx","desc":"","lua_type":"Context"},{"name":"kind","desc":"Grab, Rotate or Scale","lua_type":"Transform.Kind"},{"name":"duplicate","desc":"copy the selection first and move the copy","lua_type":"boolean"}],"returns":[{"desc":"the running action, or nil after saying why it could not start","lua_type":"Modal?"}],"function_type":"static","source":{"line":42,"path":"src/Modal/Move.luau"}}],"properties":[],"types":[],"name":"Move","desc":"Grab, rotate and scale (G, R, C), and duplicate (V then move), as in Blender. The selection\\nfollows the mouse until a click or Enter confirms or Esc cancels; X / Y / Z lock an axis, Alt+X /\\nY / Z a plane, and a typed number sets an exact value. The whole action is one undo step, and\\ncancelling puts every part back.\\n\\nThe maths lives in `Core/Transform`; this wraps it in an undo recording and the modal contract.","source":{"line":13,"path":"src/Modal/Move.luau"}}')}}]);